import {audioWindows,trackGain} from './audio-timeline.js';
import {sourceTime,gainAt,held,declickGain} from './mobile-model.js';
import {sequence,timing} from './model.js';
const mediaVoice=()=>{const value=document.createElement('audio');value.preload='auto';value.preservesPitch=false;return value};
export const previewDriftTolerance=playing=>playing?.32:.035;
const keyFor=(row,url)=>row&&url?`${row.clip.id}|${url}`:'';
const groupRows=(rows,count)=>{const grouped=Array.from({length:count},()=>[]);for(const row of rows)grouped[row.layer||0]?.push(row);return grouped};
const currentRow=(rows,t)=>{for(let i=rows.length-1;i>=0;i--){const row=rows[i];if(row.start<=t&&t<row.end)return row}return null};
const nextRow=(rows,t)=>{for(const row of rows)if(row.start>t&&row.start-t<1.5)return row;return null};

// Two voices per lane predecode clip boundaries. Web Audio adds a filtered
// feedback delay without replacing the media element playback clock.
export class AudioPreview{
 constructor(){this.context=null;this.graphs=new WeakMap();this.videoKey=null;this.videoByLayer=Array.from({length:3},()=>[]);this.lanes=Array.from({length:7},()=>({voices:[mediaVoice(),mediaVoice()],active:0}));this.voices=this.lanes.flatMap(lane=>lane.voices)}
 graph(voice){const Context=globalThis.AudioContext||globalThis.webkitAudioContext;if(!Context)return null;try{if(!this.context)this.context=new Context({latencyHint:'interactive'});let graph=this.graphs.get(voice);if(graph)return graph;const source=this.context.createMediaElementSource(voice),dry=this.context.createGain(),delay=this.context.createDelay(2),tone=this.context.createBiquadFilter(),feedback=this.context.createGain(),wet=this.context.createGain(),output=this.context.createGain();tone.type='lowpass';tone.frequency.value=9000;source.connect(dry).connect(output);source.connect(delay).connect(tone).connect(wet).connect(output);output.connect(this.context.destination);tone.connect(feedback).connect(delay);graph={dry,delay,feedback,wet,output};this.graphs.set(voice,graph);return graph}catch{return null}}
 configure(voice,audio,playing){const enabled=!!audio?.delayEnabled,graph=this.graphs.get(voice)||this.graph(voice);if(!graph)return null;const mix=enabled?audio.delayMix??.25:0,now=this.context.currentTime;graph.delay.delayTime.setTargetAtTime(audio?.delayTime??.28,now,.01);graph.feedback.gain.setTargetAtTime(enabled?audio?.delayFeedback??.35:0,now,.01);graph.wet.gain.setTargetAtTime(mix,now,.01);graph.dry.gain.setTargetAtTime(1-mix*.25,now,.01);if(playing&&this.context.state==='suspended')this.context.resume().catch(()=>{});return graph}
 prepare(lane,row,p,urlOf){const c=row?.clip,m=p.media.find(item=>item.id===c?.media),url=m&&urlOf(m),key=keyFor(row,url);if(!key)return null;let index=lane.voices.findIndex(voice=>voice.dataset.key===key);if(index<0){index=1-lane.active;const voice=lane.voices[index];voice.pause();voice.dataset.key=key;voice.dataset.url=url;voice.src=url;voice.load();const at=c.loop?sourceTime(row,row.start)%m.duration:sourceTime(row,row.start);const seek=()=>{try{voice.currentTime=at}catch{}};voice.readyState>=1?seek():voice.addEventListener('loadedmetadata',seek,{once:true})}return index}
 syncLane(lane,row,p,t,playing,urlOf,gain,loop=false){const c=row?.clip,m=p.media.find(item=>item.id===c?.media),url=m&&urlOf(m);if(!row||!url||!m?.audio||c.audio?.mute||!gain||held(row,t)){lane.voices.forEach(voice=>voice.pause());return}const index=this.prepare(lane,row,p,urlOf);if(index!==lane.active){lane.voices[lane.active].pause();lane.active=index}const voice=lane.voices[index],source=sourceTime(row,t),local=t-row.start+(row.offset||0),tm=timing(c),i=tm.nodes.findIndex(node=>node[1]>=local),speed=tm.pieces[Math.max(0,i-1)]?.[2]||1,at=loop?source%m.duration:source,graph=this.configure(voice,c.audio,playing),level=(gain*gainAt(local,tm.duration,c.audio.volume,c.audio.fadeIn,c.audio.fadeOut,c.audio.gainKeyframes,c.audio.gainEnvelope)*declickGain(local,tm.duration));voice.loop=loop;if(graph){voice.volume=1;this.scheduleGain(graph,c,local,tm.duration,gain,playing)}else voice.volume=Math.min(1,level);if(voice.readyState>=1&&!voice.seeking&&Math.abs(voice.currentTime-at)>previewDriftTolerance(playing))try{voice.currentTime=at}catch{}if(playing&&speed>=.25&&speed<=4&&!c.freezeDuration){voice.playbackRate=speed;if(voice.readyState>=2&&voice.paused)voice.play().catch(()=>{})}else voice.pause()}
 scheduleGain(graph,c,local,duration,trackVolume,playing){const now=this.context.currentTime,key=JSON.stringify([c.audio,trackVolume,duration]);if(!playing||graph.gainKey!==key||Math.abs(local-(graph.local+(now-graph.clock)))>.03||now>=graph.until-.04){const param=graph.output.gain;param.cancelScheduledValues(now);const span=playing?Math.min(.15,Math.max(.001,duration-local)):.001,count=Math.max(2,Math.ceil(span*48000)),curve=new Float32Array(count);for(let i=0;i<count;i++){const at=local+span*i/(count-1);curve[i]=trackVolume*gainAt(at,duration,c.audio.volume,c.audio.fadeIn,c.audio.fadeOut,c.audio.gainKeyframes,c.audio.gainEnvelope)*declickGain(at,duration)}if(playing)param.setValueCurveAtTime(curve,now,span);else param.setValueAtTime(curve[0],now);graph.gainKey=key;graph.local=local;graph.clock=now;graph.until=now+span}}
 primeNext(lane,rows,p,t,urlOf){const next=nextRow(rows,t);if(next)this.prepare(lane,next,p,urlOf)}
 sync(p,t,playing,urlOf){const audioByLayer=groupRows(audioWindows(p),4);for(let layer=0;layer<4;layer++){const rows=audioByLayer[layer],row=currentRow(rows,t);this.syncLane(this.lanes[3+layer],row,p,t,playing,urlOf,trackGain(p,layer),!!row?.clip.loop);this.primeNext(this.lanes[3+layer],rows,p,t,urlOf)}const solo=!!p.audioTracks?.some(track=>track.solo),videoKey=p.clips.map(c=>[c.id,c.start,c.layer,c.in,c.out,c.speed,c.endSpeed,c.curve,c.hold].join(':')).join('|');if(videoKey!==this.videoKey){this.videoKey=videoKey;this.videoByLayer=groupRows(sequence(p).filter(value=>!value.clip.gap),3)}for(let layer=0;layer<3;layer++){const rows=this.videoByLayer[layer],row=currentRow(rows,t),track=p.videoTracks?.[layer]||{};this.syncLane(this.lanes[layer],row,p,t,playing,urlOf,solo||track.hidden?0:Math.max(0,Math.min(2,track.volume??1)));this.primeNext(this.lanes[layer],rows,p,t,urlOf)}}
 pause(){this.voices.forEach(voice=>voice.pause())}
 dispose(){this.voices.forEach(voice=>{voice.pause();voice.removeAttribute('src');voice.load();delete voice.dataset.key;delete voice.dataset.url});this.context?.close?.();this.context=null;this.graphs=new WeakMap()}
}
